import assert from 'node:assert';
import { test } from 'node:test';
import { createState, frame, collides, WIDTH, HEIGHT, BRICK_W, BRICK_H, BRICK_GAP, BRICK_TOP } from './game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('D1 - Absence de rebond', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball to collide with the top of the brick
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 2; // ball.r is 7, so it overlaps by 5px
  state.ball.vy = 100; // Moving DOWN

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy, 100, 'Ball should have bounced (vy should be negative)');
});

test('D3 - Face vs Coin (Side hit flips VY)', () => {
  // This test simulates a "naive fix" where we always flip VY
  // We want to see if the current (or slightly improved) code would flip VY on a side hit
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball to collide with the LEFT side of the brick
  state.ball.x = brick.x - 2; // ball.r is 7, overlaps by 5px
  state.ball.y = brick.y + BRICK_H / 2;
  state.ball.vx = 100; // Moving RIGHT
  state.ball.vy = 0;

  frame(mockCtx, state);

  // If naive fix: vy becomes -vy (0), vx stays 100.
  // Correct fix: vx becomes -100, vy stays 0.
  assert.strictEqual(state.ball.vx, -100, 'Ball should have bounced horizontally (vx should be negative)');
});

test('D5 - Traversée (Tunneling)', () => {
  const state = createState(10); // High level = high speed
  // Level 10 speed: 260 + 9 * 90 = 1070 px/s
  // Max dt: 0.05s -> movement: 53.5 px
  // Brick height: 20px, Ball diameter: 14px. Total: 34px.
  // 53.5 > 34 -> Tunneling possible.

  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 10; // Just above the brick
  state.ball.vy = 1000; // Very fast down

  // We simulate one step that should put the ball on the other side of the brick
  const dt = 0.05;
  const oldY = state.ball.y;
  const newY = oldY + state.ball.vy * dt; // = -10 + 50 = 40
  // Brick is at BRICK_TOP (48). 
  // Wait, BRICK_TOP is 48.
  // Ball y: 48 - 10 = 38.
  // New y: 38 + 50 = 88.
  // Brick bottom: 48 + 20 = 68.
  // Ball is now at 88. 88 - 7 = 81 > 68.
  // The ball has completely passed the brick.

  state.ball.y = newY;

  // In frame(), we check collision.
  frame(mockCtx, state);

  // Since the ball is already past the brick, collides() will be false.
  // But it SHOULD have hit the brick during the transition from 38 to 88.
  // This is the essence of tunneling.
  // For now, we just check that it didn't bounce.
  assert.strictEqual(state.ball.vy, 1000, 'Ball should have been detected as colliding and bounced');
});

