import assert from 'node:assert';
import { test } from 'node:test';
import { createState, frame, WIDTH, HEIGHT, BRICK_W, BRICK_H, BRICK_GAP, BRICK_TOP } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('D1 - Absence de rebond', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 2; 
  state.ball.vy = 100; 

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy, -100, 'Ball should have bounced (vy should be negative)');
});

test('D2 - Collant (Stickiness)', () => {
  // This test will fail if we only flip vy without repositioning.
  // We simulate the "naive fix" by manually flipping vy once, then calling frame.
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 2; 
  state.ball.vy = 100; 

  // First collision: vy becomes -100
  state.ball.vy = -100; 

  // Now, we check if it's still colliding.
  // If it is, and we call frame, it should NOT flip vy back to 100.
  // But if the logic is just "if collides flip", it will flip back.
  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy, -100, 'Ball should not flip vy again if it is still overlapping after a bounce');
});

test('D3 - Face vs Coin (Side hit flips VX)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 2; 
  state.ball.y = brick.y + BRICK_H / 2;
  state.ball.vx = 100; 
  state.ball.vy = 0;

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx, -100, 'Ball should have bounced horizontally (vx should be negative)');
});

test('D4 - Double inversion (Ghost collision)', () => {
  const state = createState(1);
  // Use two bricks on the same row.
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];

  // Position ball so it collides with BOTH bricks (on the seam)
  // b1.x + b1.w = b2.x - BRICK_GAP? No, the gap is between them.
  // b1 is at offsetX, b2 at offsetX + BRICK_W + BRICK_GAP.
  // Let's put the ball exactly on the boundary.
  state.ball.y = b1.y + BRICK_H / 2;
  state.ball.x = b1.x + b1.w + BRICK_GAP / 2; // Centered on the gap
  state.ball.vx = 100; 

  // To hit both, the ball.r must be > BRICK_GAP / 2.
  // ball.r = 7. BRICK_GAP / 2 = 4.
  // So it collides with both.

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx, -100, 'Ball should have flipped vx exactly once');
});

test('D5 - Traversée (Tunneling)', () => {
  const state = createState(10); 
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 1000; 

  const dt = 0.05;
  const newY = state.ball.y + state.ball.vy * dt; 
  state.ball.y = newY;

  frame(mockCtx, state);

  assert.notStrictEqual(state.ball.vy, 1000, 'Ball should have been detected as colliding and bounced');
});

# Symptôme : La balle traverse les briques au lieu de rebondir.

## D1 — Absence de rebond

- **Famille** : Traversée / Naïf
- **Symptôme joueur** : la balle traverse les briques sans ralentir ni changer de direction.
- **Cause** : `game/neon.js:168` — `collides()` est appelé mais aucune modification de `ball.vx` ou `ball.vy` n'est effectuée.
- **Invariant violé** : Toute collision avec une brique doit entraîner un rebond.
- **Déclencheur** : N'importe quelle collision avec une brique.
- **Attendu** : La composante de la vitesse perpendiculaire à la face touchée doit être inversée.
- **Référence** : https://gamedev.net/game-programming/swept-aabb-collision-detection-and-response-r3084
- **Cas test** :
  ```js
  test('D1 - Absence de rebond', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y - 2; 
    state.ball.vy = 100; 
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vy, -100);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced (vy should be negative) 100 !== -100`
- **Discrimine** : Ce cas refuse l'absence totale de logique de rebond.
- **Vert quand** : La balle rebondit sur la face supérieure d'une brique.
- **Révélé par** : -

## D2 — Collant (Stickiness)

- **Famille** : Collant
- **Symptôme joueur** : la balle vibre ou reste coincée dans la brique.
- **Cause** : Inversion de la vitesse sans repositionnement de la balle hors du rectangle.
- **Invariant violé** : Après résolution, la balle doit être hors du rectangle.
- **Déclencheur** : Collision avec pénétration profonde telle que `abs(v * dt) < pénétration`.
- **Attendu** : La balle est repositionnée sur la face de la brique après le rebond.
- **Référence** : https://gamedev.net/game-programming/swept-aabb-collision-detection-and-response-r3084
- **Cas test** :
  ```js
  test('D2 - Collant (Stickiness)', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y - 2; 
    state.ball.vy = -100; // Already bounced
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vy, -100, 'Ball should not flip vy again if it is still overlapping');
  });
  ```
- **Rouge aujourd'hui** : Passant car D1 n'est pas encore corrigé. Sera rouge dès que D1 est corrigé naïvement.
- **Discrimine** : Refuse l'implémentation `vy = -vy` sans repositionnement.
- **Vert quand** : La balle ne rebondit pas une seconde fois si elle est toujours en recouvrement.
- **Révélé par** : D1

## D3 — Face vs Coin (Wrong axis)

- **Famille** : Face vs coin
- **Symptôme joueur** : la balle rebondit bizarrement sur les côtés des briques (ex: rebond vertical sur un hit latéral).
- **Cause** : Inversion systématique de `vy` sans tester laquelle des deux faces (X ou Y) a été touchée.
- **Invariant violé** : L'axe touché est celui de la plus petite pénétration.
- **Déclencheur** : Collision latérale (hit sur la face gauche ou droite).
- **Attendu** : `vx` est inversé, `vy` reste inchangé.
- **Référence** : https://gamedev.net/game-programming/swept-aabb-collision-detection-and-response-r3084
- **Cas test** :
  ```js
  test('D3 - Face vs Coin (Side hit flips VX)', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x - 2; 
    state.ball.y = brick.y + BRICK_H / 2;
    state.ball.vx = 100; 
    state.ball.vy = 0;
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vx, -100);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced horizontally (vx should be negative) 100 !== -100`
- **Discrimine** : Refuse l'implémentation `vy = -vy` systématique.
- **Vert quand** : La balle rebondit correctement sur les faces latérales.
- **Révélé par** : D1

## D4 — Double inversion (Ghost collision)

- **Famille** : Double inversion
- **Symptôme joueur** : la balle traverse une ligne de briques sans rebondir.
- **Cause** : Deux briques détectées dans la même frame sur une couture.
- **Invariant violé** : Un rebond par passe et par axe.
- **Déclencheur** : Collision sur la couture entre deux briques (`ball.x` proche de `brick.x + brick.w`).
- **Attendu** : La balle rebondit une seule fois.
- **Référence** : https://gamedev.net/game-programming/swept-aabb-collision-detection-and-response-r3084
- **Cas test** :
  ```js
  test('D4 - Double inversion (Ghost collision)', () => {
    const state = createState(1);
    const b1 = state.bricks[0];
    const b2 = state.bricks[1];
    state.ball.y = b1.y + BRICK_H / 2;
    state.ball.x = b1.x + b1.w + BRICK_GAP / 2;
    state.ball.vx = 100; 
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vx, -100);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have flipped vx exactly once 100 !== -100`
- **Discrimine** : Refuse l'implémentation qui boucle sur toutes les briques sans sortir du loop après le premier rebond.
- **Vert quand** : La balle rebondit une seule fois même si elle touche deux briques.
- **Révélé par** : D1, D3

## D5 — Traversée (Tunneling)

- **Famille** : Traversée
- **Symptôme joueur** : la balle passe à travers les briques à très haute vitesse.
- **Cause** : Détection discrète : un pas plus long que l'obstacle le franchit sans jamais le toucher.
- **Invariant violé** : Aucun obstacle franchi sans rebond, quel que soit le pas.
- **Déclencheur** : `ballSpeed(level) * dt > (BRICK_H + BALL_R * 2)`. Pour $dt=0.05$, cela arrive dès le niveau 6.
- **Attendu** : La collision est détectée même si la position finale est au-delà de l'obstacle.
- **Référence** : https://github.com/KleeSup/KleeSwept
- **Cas test** :
  ```js
  test('D5 - Traversée (Tunneling)', () => {
    const state = createState(10); 
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y - 10; 
    state.ball.vy = 1000; 
    state.ball.y += state.ball.vy * 0.05;
    frame(mockCtx, state);
    assert.notStrictEqual(state.ball.vy, 1000);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have been detected as colliding and bounced`
- **Discrimine** : Refuse la détection discrète simple.
- **Vert quand** : La balle rebondit même à très haute vitesse.
- **Révélé par** : D1

