import assert from 'node:assert';
import { test } from 'node:test';
import { createState, step, WIDTH, HEIGHT, BRICK_W, BRICK_H, BRICK_GAP, BRICK_TOP } from '../game/neon.js';

test('D1 - Absence de rebond', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 2; 
  state.ball.vy = 100; 

  step(state, 0.01); // Small dt to trigger collision in step

  assert.strictEqual(state.ball.vy, -100, 'Ball should have bounced (vy should be negative)');
});

test('D2 - Collant (Stickiness)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 2; 
  state.ball.vy = -100; // Already bounced

  step(state, 0.01);

  assert.strictEqual(state.ball.vy, -100, 'Ball should not flip vy again if it is still overlapping after a bounce');
});

test('D3 - Face vs Coin (Side hit flips VX)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 2; 
  state.ball.y = brick.y + BRICK_H / 2;
  state.ball.vx = 100; 
  state.ball.vy = 0;

  step(state, 0.01);

  assert.strictEqual(state.ball.vx, -100, 'Ball should have bounced horizontally (vx should be negative)');
});

test('D4 - Double inversion (Ghost collision)', () => {
  const state = createState(1);
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];
  state.ball.y = b1.y + BRICK_H / 2;
  state.ball.x = b1.x + b1.w + BRICK_GAP / 2;
  state.ball.vx = 100; 

  step(state, 0.01);

  assert.strictEqual(state.ball.vx, -100, 'Ball should have flipped vx exactly once');
});

test('D5 - Traversée (Tunneling)', () => {
  const state = createState(10); 
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 1000; 

  step(state, 0.05); // Use max dt

  assert.notStrictEqual(state.ball.vy, 1000, 'Ball should have been detected as colliding and bounced');
});

