export function step(state, dt) {
  const { ball, paddle } = state;

  let remainingDt = dt;
  const sdt = 0.002; // 2ms fixed sub-step

  while (remainingDt > 0) {
    const currentDt = Math.min(sdt, remainingDt);
    ball.x += ball.vx * currentDt;
    ball.y += ball.vy * currentDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Bricks
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      if (collides(ball, brick)) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);

        const overlapLeft = (ball.x + ball.r) - brick.x;
        const overlapRight = (brick.x + brick.w) - (ball.x - ball.r);
        const overlapTop = (ball.y + ball.r) - brick.y;
        const overlapBottom = (brick.y + brick.h) - (ball.y - ball.r);

        const minX = Math.min(overlapLeft, overlapRight);
        const minY = Math.min(overlapTop, overlapBottom);

        if (minX < minY) {
          if (overlapLeft < overlapRight && ball.vx > 0) {
            ball.vx = -Math.abs(ball.vx);
            ball.x = brick.x - ball.r;
          } else if (overlapRight < overlapLeft && ball.vx < 0) {
            ball.vx = Math.abs(ball.vx);
            ball.x = brick.x + brick.w + ball.r;
          }
        } else if (minY < minX) {
          if (overlapTop < overlapBottom && ball.vy > 0) {
            ball.vy = -Math.abs(ball.vy);
            ball.y = brick.y - ball.r;
          } else if (overlapBottom < overlapTop && ball.vy < 0) {
            ball.vy = Math.abs(ball.vy);
            ball.y = brick.y + brick.h + ball.r;
          }
        } else {
          ball.vx = -ball.vx;
          ball.vy = -ball.vy;
          if (overlapLeft < overlapRight) ball.x = brick.x - ball.r; else ball.x = brick.x + brick.w + ball.r;
          if (overlapTop < overlapBottom) ball.y = brick.y - ball.r; else ball.y = brick.y + brick.h + ball.r;
        }
      }
    }
    remainingDt -= currentDt;
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  if (ball.y - ball.r > HEIGHT) return true;
  return false;
}

